-- vyora-ai-providers — publication de l'artefact (20833 caractères, 5 tranches).
-- Généré par scripts/build-edge-loader.mjs : ne pas éditer.
delete from public._edge_function_artifact_slices where name = 'vyora-ai-providers';

insert into public._edge_function_artifact_slices(name, part, chunk)
values
  ('vyora-ai-providers', 0, ''),
  ('vyora-ai-providers', 1, ''),
  ('vyora-ai-providers', 2, ''),
  ('vyora-ai-providers', 3, ''),
  ('vyora-ai-providers', 4, '');

-- Le chargeur déployé recompose exactement ces tranches : on vérifie ici ce
-- qu'il lira, et non une constante recopiée à la main.
do $artifact$
declare
  assembled text;
  parts integer;
begin
  select count(*), string_agg(chunk, '' order by part)
    into parts, assembled
  from public._edge_function_artifact_slices where name = 'vyora-ai-providers';

  if assembled is null or parts <> 5 then
    raise exception 'artefact % : % tranches publiées au lieu de %',
      'vyora-ai-providers', coalesce(parts, 0), 5;
  end if;
  if exists (
    select 1 from public._edge_function_artifact_slices
    where name = 'vyora-ai-providers'
      and (part < 0 or part >= 5
           or length(chunk) = 0 or length(chunk) > 2000)
  ) then
    raise exception 'artefact % : numérotation ou taille de tranche invalide', 'vyora-ai-providers';
  end if;
  if length(assembled) <> 9752 then
    raise exception 'artefact % : % caractères base64 au lieu de %',
      'vyora-ai-providers', length(assembled), 9752;
  end if;
  if md5(assembled) <> '4f137e4c991aa873c03b51452c2a0208' then
    raise exception 'artefact % : empreinte des tranches différente du chargeur', 'vyora-ai-providers';
  end if;
  raise notice 'artefact % publié : % caractères, % tranches, sha256 %',
    'vyora-ai-providers', 20833, 5, 'c280d6f2a0123afea9bc63a2d23530dcb00b457ed56c954583eaf0459ddcbc69';
end
$artifact$;
